// Package copygen is every word the companion shows a player: the window's (through
// ui/copy_gen.js, the same keys), the tray's, the install windows' and the Go side's headline,
// addon row and failure messages. The constants are generated by web/scripts/gen-mobile-copy.mjs
// from apps/shared/copy/companion.json, so a word reads the same in the window, the tray and the
// Go side. Never edit copy_gen.go: edit the JSON and run `node web/scripts/gen-mobile-copy.mjs`.
//
// A text's {name} markers are filled with Fill; a Plural picks its form with For.
package copygen

import (
	"strconv"
	"strings"
)

// Fill replaces each marker with its value: Fill("Addon not found in {folder}", "{folder}", "_forever_").
// pairs alternate marker and value, the way strings.NewReplacer takes them.
func Fill(text string, pairs ...string) string {
	return strings.NewReplacer(pairs...).Replace(text)
}

// Plural is a counted text: One for a count of one, Other (which shows {Count}) for the rest.
type Plural struct {
	// Count is the placeholder the count fills, without braces.
	Count string
	// One and Other are the two forms.
	One, Other string
}

// For is the form for n with the count filled in: "1 fight", "3 fights".
func (p Plural) For(n int) string {
	form := p.Other
	if n == 1 {
		form = p.One
	}
	return Fill(form, "{"+p.Count+"}", strconv.Itoa(n))
}
